                },
            },
        },
        "fits": {
            "type": "array",
            "description": "Per-salt Langmuir fit parameters as reconstructed from the CSV file (if available)",
            "items": {
                "type": "object",
                "properties": {
                    "salt_conc": {
                        "type": "number",
                        "description": "Salt concentration for this fit",
                    },
                    "q_max": {
