                },
                "raw_tecan_excel": {
                    "type": "string",
                    "description": "Path to raw Tecan Excel file used in analysis",
                },
                "well_level_csv": {
                    "type": "string",
                    "description": "CSV file with well-level data",
                },
                "aggregated_isotherm_csv": {
                    "type": "string",
                    "description": "CSV file with aggregated isotherm data",
                },
