// Extract structured schemas + commit script from AI Agent fenced output
const raw = $input.item.json.output || $input.item.json.text || "";

// --- Extract JSON schema block ---
let schemas = {};
const jsonBlock = raw.match(/```json\s*\n([\s\S]*?)\n\s*```/);
if (jsonBlock) {
  try {
    schemas = JSON.parse(jsonBlock[1]);
  } catch (e) {
    let cleaned = jsonBlock[1]
      .replace(/,\s*}/g, '}')
      .replace(/,\s*]/g, ']');
    try {
      schemas = JSON.parse(cleaned);
    } catch (e2) {
      throw new Error(`Failed to parse JSON block: ${e2.message}`);
    }
  }
} else {
  // Fallback: maybe the output IS already JSON (no fences)
  try {
    schemas = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    throw new Error("No ```json block found and raw output is not valid JSON.");
  }
}

// --- Extract Python commit script block ---
let commitScript = "";
const pyBlock = raw.match(/```python\s*\n([\s\S]*?)\n\s*```/);
if (pyBlock) {
  commitScript = pyBlock[1];
} else if (schemas.commit_script) {
  commitScript = schemas.commit_script;
  delete schemas.commit_script;
}

return {
  json: {
    parameters_schema: schemas.parameters_schema || {},
    results_schema: schemas.results_schema || {},
    field_mapping: schemas.field_mapping || {},
    expected_data_files: schemas.expected_data_files || [],
    expected_plot_files: schemas.expected_plot_files || [],
    commit_script: commitScript
  }
};

